/**
 * The pure half of `scripts/build-worklets.mjs` (#643): which worklet sources
 * bundle into which generated file, the header every generated file opens
 * with, and the esbuild options that keep the output a faithful concatenation
 * of its modules.
 *
 * A worklet reaches its three consumers as one script: Vite's `new URL(...)`
 * emits the file as an asset, the console inlines it behind a blob URL (which
 * cannot resolve an import), and the test harness evaluates its text under
 * Node. The bundle is what lets the *source* be many files. It is bundled and
 * nothing else: no minification, no syntax lowering, no tree shaking. The
 * DSP's bit-identity holds by the same IEEE operations in the same order, and
 * the harness reaches the worklet's internals by their top-level names, so a
 * transform that reorders an expression or drops a "unused" constant is a
 * broken build, not a smaller one. `fmProcessorGolden.test.ts` is the gate.
 */
/* global URL */
import { build } from 'esbuild';
import { existsSync } from 'node:fs';
import { dirname, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = fileURLToPath(new URL('../..', import.meta.url));

/** `packages/engine/src/worklet`: the sources under it, the outputs under its `generated/`. */
export const WORKLET_DIR = resolve(root, 'packages/engine/src/worklet');

export const REBUILD_COMMAND = 'node scripts/build-worklets.mjs';

/**
 * One row per worklet: the entry module and the generated file, both relative
 * to `WORKLET_DIR`. A second worklet is a second row; nothing else changes.
 */
export const WORKLETS = [
  { name: 'fm', entry: 'fm/fmProcessor.ts', output: 'generated/fm-processor.js' },
  {
    name: 'advancedDrive',
    entry: 'advancedDrive/advancedDriveProcessor.ts',
    output: 'generated/advanced-drive-processor.js',
  },
  {
    name: 'meter',
    entry: 'meter/peakMeterProcessor.ts',
    output: 'generated/peak-meter-processor.js',
  },
  {
    name: 'compressor',
    entry: 'compressor/compressorProcessor.ts',
    output: 'generated/compressor-processor.js',
  },
  { name: 'reverb', entry: 'reverb/reverbProcessor.ts', output: 'generated/reverb-processor.js' },
  {
    name: 'phaser',
    entry: 'phaser/phaserProcessor.ts',
    output: 'generated/phaser-processor.js',
  },
  {
    name: 'retro',
    entry: 'retro/retroReverbProcessor.ts',
    output: 'generated/retro-reverb-processor.js',
  },
  { name: 'delay', entry: 'delay/delayProcessor.ts', output: 'generated/delay-processor.js' },
  {
    name: 'outputStage',
    entry: 'outputStage/outputStageProcessor.ts',
    output: 'generated/output-stage-processor.js',
  },
];

/** The directory an agent edits instead of the generated file, relative to `WORKLET_DIR`. */
export const sourceDirOf = (worklet) => dirname(worklet.entry);

/** The two lines every generated file opens with. What a reader of the output needs to know, first. */
export function bannerFor(worklet) {
  const source = `packages/engine/src/worklet/${sourceDirOf(worklet)}/`;
  return [
    `// GENERATED by \`${REBUILD_COMMAND}\` from ${source}${worklet.entry.slice(sourceDirOf(worklet).length + 1)} and its imports. Do not edit.`,
    `// Edit the source under ${source} and rebuild; \`${REBUILD_COMMAND} --check\` in \`npm run verify\` refuses a stale or hand-edited copy.`,
  ].join('\n');
}

/** The esbuild options for one worklet. Pure, so the test can check the shape without esbuild. */
export function bundleOptions(worklet, workletDir = WORKLET_DIR) {
  return {
    entryPoints: [resolve(workletDir, worklet.entry)],
    bundle: true,
    write: false,
    format: 'esm',
    platform: 'browser',
    // No lowering: the source's syntax and operations, in the source's order.
    target: 'esnext',
    minify: false,
    // The harness reads constants the DSP itself never references; keep them.
    treeShaking: false,
    legalComments: 'none',
    charset: 'utf8',
    banner: { js: bannerFor(worklet) },
  };
}

/** Bundle one worklet and return the generated file's text. Throws on an entry that is missing. */
export async function bundleWorklet(worklet, workletDir = WORKLET_DIR) {
  const options = bundleOptions(worklet, workletDir);
  const [entry] = options.entryPoints;
  if (!existsSync(entry))
    throw new Error(`build-worklets: ${worklet.entry} is missing under ${workletDir}`);
  const result = await build(options);
  const [output] = result.outputFiles;
  if (!output) throw new Error(`build-worklets: ${worklet.name} produced no output`);
  return output.text;
}
